 56→// droidSettings represents the ~/.factory/settings.json structure used for
 57→// BYOK (Bring Your Own Key) configuration.
 58→type droidSettings struct {
 59→	CustomModels []droidCustomModel `json:"customModels,omitempty"`
 60→}
 61→
 62→type droidCustomModel struct {
 63→	DisplayName    string `json:"displayName"`
 64→	Model          string `json:"model"`
 65→	BaseURL        string `json:"baseUrl"`
 66→	APIKey         string `json:"apiKey"`
 67→	Provider       string `json:"provider"`
 68→	MaxOutputToken int    `json:"maxOutputTokens"`
 69→}
