 71→const (
 72→	// Droid v0.63+ expects custom model selection using custom:<model-id>.
 73→	// The displayName in settings is not accepted by --model.
 74→	droidCustomModelDisplayName = "claude-haiku-custom"
 75→	droidCustomModelBaseID      = "claude-haiku-4-5-20251001"
 76→	defaultDroidModel           = "custom:" + droidCustomModelBaseID
 77→)
