 40→func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
 41→	t.Helper()
 42→
 43→	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""
 44→
 45→	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
 46→	// creates nested subdirectories (TestName.../001/) whose structure
 47→	// confuses some agents' (e.g. opencode) working-directory resolution.
 48→	dir, err := os.MkdirTemp("", "e2e-repo-*")
 49→	if err != nil {
 50→		t.Fatalf("create temp dir: %v", err)
 51→	}
 52→	if keepRepos {
 53→		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
 54→	} else {
 55→		t.Cleanup(func() { os.RemoveAll(dir) })
 56→	}
 57→
 58→	// Resolve symlinks (macOS: /var -> /private/var) so paths match
 59→	// what agent CLIs see when they resolve their own CWD.
 60→	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
 61→		dir = resolved
 62→	}
 63→
 64→	Git(t, dir, "init")
 65→	Git(t, dir, "config", "user.name", "E2E Test")
 66→	Git(t, dir, "config", "user.email", "e2e@test.local")
 67→	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")
 68→
 69→	entire.Enable(t, dir, agent.EntireAgent())
 70→	if agent.Name() == "factoryai-droid" {
 71→		if err := configureDroidRepoSettings(dir); err != nil {
 72→			t.Fatalf("configure droid repo settings: %v", err)
 73→		}
 74→	}
 75→	PatchSettings(t, dir, map[string]any{"log_level": "debug"})
 76→
 77→	// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
 78→	// repos that lack .github/copilot-instructions.md, preventing the interactive
 79→	// prompt from appearing.
 80→	if agent.Name() == "copilot-cli" {
 81→		ghDir := filepath.Join(dir, ".github")
 82→		if err := os.MkdirAll(ghDir, 0o755); err != nil {
 83→			t.Fatalf("create .github dir: %v", err)
 84→		}
 85→		if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
 86→			t.Fatalf("write copilot-instructions.md: %v", err)
 87→		}
 88→	}
 89→
 90→	// OpenCode's non-interactive mode auto-rejects external_directory permission
 91→	// since there's no user to prompt. Write a config to allow it.
 92→	if agent.Name() == "opencode" {
 93→		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
 94→		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
 95→			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
 96→		}
 97→		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
 98→			t.Fatalf("write opencode.json: %v", err)
 99→		}
100→	}
101→
102→	// Create artifact dir eagerly so console.log is written to disk
103→	// incrementally. Even if the test is killed by a global timeout,
104→	// partial output survives.
105→	artDir := artifactDir(t)
106→	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
107→	if err != nil {
108→		t.Fatalf("create console.log: %v", err)
109→	}
110→
111→	state := &RepoState{
112→		Agent:            agent,
113→		Dir:              dir,
114→		ArtifactDir:      artDir,
115→		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
116→		CheckpointBefore: GitOutput(t, dir, "rev-parse", "entire/checkpoints/v1"),
117→		ConsoleLog:       consoleLog,
118→	}
119→
120→	t.Cleanup(func() {
121→		_ = consoleLog.Close()
122→		if !state.skipArtifacts {
123→			CaptureArtifacts(t, state)
124→		}
125→	})
126→
127→	return state
128→}
