130→func configureDroidRepoSettings(repoDir string) error {
131→	home, err := os.UserHomeDir()
132→	if err != nil {
133→		return fmt.Errorf("get home dir: %w", err)
134→	}
135→
136→	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
137→	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)
138→
139→	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
140→		return err
141→	}
142→	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
143→		return fmt.Errorf("exclude droid settings from git: %w", err)
144→	}
145→	return nil
146→}
