831→// cleanupShadowBranchIfUnused deletes a shadow branch if no other active sessions reference it.
832→func (s *ManualCommitStrategy) cleanupShadowBranchIfUnused(ctx context.Context, _ *git.Repository, shadowBranchName, excludeSessionID string) error {
833→	// List all session states to check if any other session uses this shadow branch
834→	allStates, err := s.listAllSessionStates(ctx)
835→	if err != nil {
836→		return fmt.Errorf("failed to list session states: %w", err)
837→	}
838→
839→	for _, state := range allStates {
840→		if state.SessionID == excludeSessionID {
841→			continue
842→		}
843→		otherShadow := getShadowBranchNameForCommit(state.BaseCommit, state.WorktreeID)
844→		if otherShadow == shadowBranchName && state.StepCount > 0 {
845→			// Another session still needs this shadow branch
846→			return nil
847→		}
848→	}
849→
850→	// No other sessions need it, delete the shadow branch via CLI
851→	// (go-git v5's RemoveReference doesn't persist with packed refs/worktrees)
852→	if err := DeleteBranchCLI(ctx, shadowBranchName); err != nil {
853→		// Branch already gone is not an error
854→		if errors.Is(err, ErrBranchNotFound) {
855→			return nil
856→		}
857→		return fmt.Errorf("failed to remove shadow branch: %w", err)
858→	}
859→	return nil
860→}
