250→// marshalHookType marshals a hook type back to rawHooks.
251→// If the slice is empty, removes the key from rawHooks.
252→func marshalHookType(rawHooks map[string]json.RawMessage, hookType string, matchers []FactoryHookMatcher) {
253→	if len(matchers) == 0 {
254→		delete(rawHooks, hookType)
255→		return
256→	}
257→	data, err := json.Marshal(matchers)
258→	if err != nil {
259→		return // Silently ignore marshal errors (shouldn't happen)
260→	}
261→	rawHooks[hookType] = data
262→}
